<h2>Estimate days in accounts receivable</h2><p class="lead">Divide aggregate A/R by average daily charges to create a simple RCM aging indicator.</p><div class="form-grid"><div class="field"><label for="ar">Total accounts receivable</label><input id="ar" type="number" min="0" step="0.01" value="850000"></div><div class="field"><label for="charges">Average daily charges</label><input id="charges" type="number" min="0" step="0.01" value="22000"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc">Calculate days in A/R</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Estimated days in A/R</span><strong id="days">—</strong></div><div class="metric"><span>A/R balance</span><strong id="balance">—</strong></div><div class="metric"><span>Average daily charges</span><strong id="daily">—</strong></div></div></div><div class="notice"><strong>Privacy:</strong> Use aggregate financial totals only; do not enter PHI or patient-level balances.</div>
<script>(()=>{const $=i=>document.getElementById(i),n=i=>Math.max(0,parseFloat($(i).value)||0),m=x=>'$'+x.toLocaleString(undefined,{maximumFractionDigits:2});function go(){const a=n('ar'),c=n('charges');$('days').textContent=c>0?(a/c).toFixed(1)+' days':'—';$('balance').textContent=m(a);$('daily').textContent=m(c)}document.querySelectorAll('input').forEach(x=>x.addEventListener('input',go));$('calc').onclick=go;go()})();</script>
